
using UnityEngine;
using UnityEngine.UI;

// Generated by ChatGPT
public class ScoreManager : MonoBehaviour
{
    [Header("Score Settings")]
    [SerializeField] private Text scoreLabel;

    [SerializeField] private int pointsPerWaste = 10;
    [SerializeField] private int pointsPerZone = 100;

    private int totalPoints;

    private void Awake()
    {
        totalPoints = 0;
        UpdateScoreText();
    }

    private void OnEnable()
    {
        Collectible.Collected += OnWasteCollected;
        ForestRecovery.ZoneRecovered += OnZoneRecovered;
    }

    private void OnDisable()
    {
        Collectible.Collected -= OnWasteCollected;
        ForestRecovery.ZoneRecovered -= OnZoneRecovered;
    }

    private void OnWasteCollected(Collectible item)
    {
        AddPoints(pointsPerWaste);
    }

    private void OnZoneRecovered(int zone)
    {
        AddPoints(pointsPerZone);
    }

    private void AddPoints(int points)
    {
        totalPoints += points;
        UpdateScoreText();
    }

    private void UpdateScoreText()
    {
        if (scoreLabel != null)
            scoreLabel.text = "Puntos: " + totalPoints;
    }
}
